import os
import re

from pathlib import Path
from auto_config.generator.utils.utils import get_yaml_file, sorting_key
from auto_config.generator.utils.logger import logger


ENB_PARAMS_PATH = Path(os.path.abspath(__file__)).parents[2] / "config" / "ENB_PARAMS"


def get_enb_params(pddb_release_filename):
    if os.path.exists(os.path.join(ENB_PARAMS_PATH, pddb_release_filename + '.yaml')):
        logger.info(f"Using ENB Params: {pddb_release_filename}")
        return get_yaml_file(os.path.join(ENB_PARAMS_PATH, pddb_release_filename + '.yaml'))

    # if file is not found, take latest available enb_params file with lower release version

    logger.info(f'ENB Params file: {pddb_release_filename} not found. Searching for a lower version...')
    build_type = re.search(r'^(\D+)', pddb_release_filename).group(1)

    enb_params_files = []
    for f in os.listdir(ENB_PARAMS_PATH):
        if (f.startswith(build_type)
            and os.path.isfile(os.path.join(ENB_PARAMS_PATH, f))
            and (('FSM3' in pddb_release_filename and 'FSM3' in f)
                 or ('FSM3' not in pddb_release_filename and 'FSM3' not in f))):
            enb_params_files.append(f)

    # filter out higher versions of enb_params
    enb_params_files = list(
        filter(
            lambda x: sorting_key(x) <= sorting_key(pddb_release_filename), enb_params_files
        )
    )
    if enb_params_files:
        enb_params_filename = sorted(enb_params_files, key=sorting_key)[-1]
    else:
        logger.info(f'No BTS params file for build type: {build_type}')
        return {}
    logger.info(f'Lower ENB Params version found: {enb_params_filename.rstrip(".yaml")}')
    return get_yaml_file(os.path.join(ENB_PARAMS_PATH, enb_params_filename))
